@startuml ClassDiagram
class Game {
  - id: string
  - score: int
  + play(): void
  + viewScore(): int
}
class Question {
  - id: string
  - prompt: string
  - options: List<string>
  + getPrompt(): string
  + getOptions(): List<string>
}
class User {
  - id: string
  - username: string
  + playGame(game: Game): void
  + viewScore(game: Game): int
}
class Admin {
  - id: string
  - username: string
  + updateQuestions(questions: List<Question>): void
}
Game --* Question
User --* Game
Admin --* Question
@enduml

